able":"xpert_project_pipeline_refresh","name":"FK_191e6fb01a779d0c1bd12e2dfca","definition":"FOREIGN KEY (\"organizationId\") REFERENCES organization(id) ON UPDATE CASCADE ON DELETE CASCADE","validated":true},{"table":"xpert_project_pipeline_refresh","name":"FK_444fc3b5e5de935d42d2d8bc5ef","definition":"FOREIGN KEY (\"createdById\") REFERENCES \"user\"(id) ON DELETE RESTRICT","validated":true},{"table":"xpert_project_pipeline_round","name":"FK_0fae4e4df54f5b0818b8edecc7e","definition":"FOREIGN KEY (\"projectId\") REFERENCES xpert_project(id) ON UPDATE CASCADE ON DELETE CASCADE","validated":true},{"table":"xpert_project_pipeline_round","name":"FK_40beb4198d5e7a5e8fc7c078003","definition":"FOREIGN KEY (\"organizationId\") REFERENCES organization(id) ON UPDATE CASCADE ON DELETE CASCADE","validated":true},{"table":"xpert_project_pipeline_run","name":"FK_6284025cb8f4676259abe4f2fe4","definition":"FOREIGN KEY (\"updatedById\") REFERENCES \"user\"(id) ON DELETE RESTRICT","validated":true},{"table":"xpert_project_pipeline_task_link","name":"FK_168158972ba37b67c3f79d56d89","definition":"FOREIGN KEY (\"updatedById\") REFERENCES \"user\"(id) ON DELETE RESTRICT","validated":true},{"table":"xpert_project_pipeline_task_link","name":"FK_498848f165da96907ba6ad0b589","definition":"FOREIGN KEY (\"tenantId\") REFERENCES tenant(id) ON DELETE CASCADE","validated":true},{"table":"xpert_project_task","name":"FK_2253ba272431f0c6d1a035bbad9","definition":"FOREIGN KEY (\"tenantId\") REFERENCES tenant(id) ON DELETE CASCADE","validated":true},{"table":"xpert_project_task_execution","name":"FK_3c3f62899cf0b0d16f2691df275","definition":"FOREIGN KEY (\"createdById\") REFERENCES \"user\"(id) ON DELETE RESTRICT","validated":true},{"table":"xpert_project_task_execution","name":"FK_5f6ffee42e79426450e5e40812f","definition":"FOREIGN KEY (\"organizationId\") REFERENCES organization(id) ON UPDATE CASCADE ON DELETE CASCADE","validated":true},{"table":"xpert_task_execution","name":"FK_4222a2ce255639c5818ac21756c","definition":"FOREIGN KEY (\"organizationId\") REFERENCES organization(id) ON UPDATE CASCADE ON DELETE CASCADE","validated":true}],"indexes":[]}$catalog$::jsonb AS catalog),
columns AS (
  SELECT c.relname AS "table", a.attname AS name, format_type(a.atttypid,a.atttypmod) AS type,
    a.attnotnull AS "notNull", pg_get_expr(d.adbin,d.adrelid) AS "default"
  FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace
  LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
  WHERE n.nspname=current_schema() AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped
),
constraints AS (
  SELECT t.relname AS "table", c.conname AS name, pg_get_constraintdef(c.oid) AS definition,
    c.convalidated AS validated FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid
  JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=current_schema()
),
indexes AS (
  SELECT t.relname AS "table", c.relname AS name, pg_get_indexdef(i.indexrelid) AS definition, i.indisvalid AS valid
  FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_class t ON t.oid=i.indrelid
  JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=current_schema()
)
SELECT 'column:'||e."table"||'.'||e.name AS missing FROM expected,
  jsonb_to_recordset(catalog->'columns') AS e("table" text,name text,type text,"notNull" boolean,"default" text)
WHERE NOT EXISTS (SELECT 1 FROM columns a WHERE a."table"=e."table" AND a.name=e.name AND a.type=e.type
  AND a."notNull"=e."notNull" AND a."default" IS NOT DISTINCT FROM e."default")
UNION ALL
SELECT 'constraint:'||e."table"||'.'||e.name FROM expected,
  jsonb_to_recordset(catalog->'constraints') AS e("table" text,name text,definition text,validated boolean,alternatives text[])
WHERE NOT EXISTS (SELECT 1 FROM constraints a WHERE a."table"=e."table" AND a.name=e.name
  AND (a.definition=e.definition OR a.definition=ANY(e.alternatives)) AND a.validated=e.validated)
UNION ALL
SELECT 'index:'||e."table"||'.'||e.name FROM expected,
  jsonb_to_recordset(catalog->'indexes') AS e("table" text,name text,definition text,valid boolean,alternatives text[])
WHERE NOT EXISTS (SELECT 1 FROM indexes a WHERE a."table"=e."table" AND a.name=e.name
  AND (a.definition=e.definition OR a.definition=ANY(e.alternatives)) AND a.valid=e.valid);
